{"path": "src/scraper.js", "content": "const Parser = require('rss-parser');
const parser = new Parser();

// simple RSS scraper that returns a few recent headlines
async function scrapeReutersBusiness(limit = 5) {
  // Reuters business RSS
  const feed = await parser.parseURL('https://www.reuters.com/tools/rss');
  // The page contains links to feeds; but the top stories feed is at https://www.reuters.com/business/finance/rss
  // To be robust, try the finance feed
  try {
    const feed2 = await parser.parseURL('https://www.reuters.com/business/finance/rss');
    const items = feed2.items.slice(0, limit).map(i => ({
      headline: i.title,
      link: i.link,
      source: 'reuters',
      timestamp: i.pubDate ? new Date(i.pubDate) : new Date()
    }));
    return items;
  } catch (e) {
    // fallback: try feed items from initial parse
    const items = feed.items.slice(0, limit).map(i => ({
      headline: i.title,
      link: i.link,
      source: 'reuters-fallback',
      timestamp: i.pubDate ? new Date(i.pubDate) : new Date()
    }));
    return items;
  }
}

module.exports = { scrapeReutersBusiness };
"}

